result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/physics.ts", "content": "export interface Vec2 {
  x: number;
  y: number;
}

export interface Body {
  mass: number;
  position: Vec2;
  velocity: Vec2;
}

function dot(a: Vec2, b: Vec2): number {
  return a.x * b.x + a.y * b.y;
}

/**
 * Resolve a collision between two circular bodies along the given normal
 * (unit vector pointing from A toward B).
 *
 * Computes the relative velocity along the normal and applies an impulse
 *   j = -(1 + e) * velAlongNormal / (1/mA + 1/mB)
 * where e is the coefficient of restitution. Bodies that are already
 * separating (velAlongNormal > 0) receive no impulse.
 */
export function resolve(a: Body, b: Body, normal: Vec2, restitution: number): void {
  const relative: Vec2 = {
    x: b.velocity.x - a.velocity.x,
    y: b.velocity.y - a.velocity.y,
  };

  const velAlongNormal = dot(relative, normal);

  // Already separating: no impulse.
  if (velAlongNormal > 0) return;

  const invMassSum = 1 / a.mass + 1 / b.mass;

  const j = (-(1 + restitution) * velAlongNormal) / invMassSum;

  const impulse: Vec2 = { x: j * normal.x, y: j * normal.y };

  a.velocity.x -= impulse.x / a.mass;
  a.velocity.y -= impulse.y / a.mass;
  b.velocity.x += impulse.x / b.mass;
  b.velocity.y += impulse.y / b.mass;
}
"})
