result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/physics.test.ts", "content": "import { describe, expect, it } from "vitest";
import { resolve, type Body, type Vec2 } from "./physics";

function body(mass: number, position: Vec2, velocity: Vec2): Body {
  return { mass, position, velocity };
}

function momentum(a: Body, b: Body): Vec2 {
  return {
    x: a.mass * a.velocity.x + b.mass * b.velocity.y === 0 ? NaN : a.mass * a.velocity.x + b.mass * b.velocity.x,
    y: a.mass * a.velocity.y + b.mass * b.velocity.y,
  };
}

describe("circle-circle impulse resolution", () => {
  it("equal masses head-on with e=1 exactly swap velocities", () => {
    const a = body(1, { x: -0.5, y: 0 }, { x: 3, y: 0 });
    const b = body(1, { x: 0.5, y: 0 }, { x: -2, y: 0 });
    const normal = { x: 1, y: 0 }; // from A toward B

    const before = momentum(a, b);
    resolve(a, b, normal, 1);
    const after = momentum(a, b);

    expect(a.velocity.x).toBeCloseTo(-2, 12);
    expect(a.velocity.y).toBe(0);
    expect(b.velocity.x).toBeCloseTo(3, 12);
    expect(b.velocity.y).toBe(0);

    expect(after.x - before.x).toBeLessThan(1e-9);
    expect(Math.abs(after.x - before.x)).toBeLessThan(1e-9);
    expect(Math.abs(after.y - before.y)).toBeLessThan(1e-9);
  });

  it("equal masses head-on with e=0 leaves both at the common momentum-conserving velocity", () => {
    const a = body(1, { x: -0.5, y: 0 }, { x: 4, y: 0 });
    const b = body(1, { x: 0.5, y: 0 }, { x: -1, y: 0 });
    const normal = { x: 1, y: 0 };

    // common velocity = (m*v_a + m*v_b) / (2m) = (4 + -1)/2 = 1.5
    const before = momentum(a, b);
    resolve(a, b, normal, 0);
    const after = momentum(a, b);

    expect(a.velocity.x).toBeCloseTo(1.5, 12);
    expect(b.velocity.x).toBeCloseTo(1.5, 12);

    expect(Math.abs(after.x - before.x)).toBeLessThan(1e-9);
    expect(Math.abs(after.y - before.y)).toBeLessThan(1e-9);
  });

  it("unequal masses head-on conserves momentum exactly", () => {
    const a = body(2, { x: -0.5, y: 0 }, { x: 6, y: 0 });
    const b = body(5, { x: 0.5, y: 0 }, { x: -1, y: 0 });
    const normal = { x: 1, y: 0 };

    const before = momentum(a, b);
    resolve(a, b, normal, 0.8); // partially elastic
    const after = momentum(a, b);

    expect(Math.abs(after.x - before.x)).toBeLessThan(1e-9);
    expect(Math.abs(after.y - before.y)).toBeLessThan(1e-9);

    // relative velocity along normal should be scaled by -e
    const relAfter = (b.velocity.x - a.velocity.x) * normal.x + (b.velocity.y - a.velocity.y) * normal.y;
    expect(relAfter).toBeCloseTo(-0.8 * (before.x / 1), 12); // placeholder replaced below
  });

  it("diagonal collision conserves momentum to 1e-9", () => {
    const len = Math.SQRT1_2;
    const normal = { x: len, y: len };
    const a = body(3, { x: 0, y: 0 }, { x: 2, y: 1 });
    const b = body(1.5, { x: 1, y: 1 }, { x: -0.5, y: -2 });

    const before = momentum(a, b);
    resolve(a, b, normal, 0.65);
    const after = momentum(a, b);

    expect(Math.abs(after.x - before.x)).toBeLessThan(1e-9);
    expect(Math.abs(after.y - before.y)).toBeLessThan(1e-9);
  });

  it("separating bodies receive zero impulse", () => {
    const a = body(1, { x: -0.5, y: 0 }, { x: -3, y: 0 }); // moving away left
    const b = body(1, { x: 0.5, y: 0 }, { x: 2, y: 0 }); // moving away right
    const normal = { x: 1, y: 0 };

    const vaBefore = { ...a.velocity };
    const vbBefore = { ...b.velocity };

    resolve(a, b, normal, 1);

    expect(a.velocity.x).toBe(vaBefore.x);
    expect(a.velocity.y).toBe(vaBefore.y);
    expect(b.velocity.x).toBe(vbBefore.x);
    expect(b.velocity.y).toBe(vbBefore.y);
  });
});
"})
